#!/usr/bin/env python3
"""Analyze the small same-span P5-orthogonal background numerical audit."""
import argparse,hashlib,json,os,tempfile
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--probe',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output;out.mkdir(exist_ok=False);path=a.probe/'probe.stdout';rows=[json.loads(l) for l in path.read_text().splitlines()];plans=[r for r in rows if r['phase']=='plan'];weights=[r for r in rows if r['phase']=='physical_weights'];fields=[r for r in rows if r['phase']=='field'];precision=next(r for r in rows if r['phase']=='precision');summary=next(r for r in rows if r['phase']=='summary');assert len(plans)==24 and all(r['within_1e_9'] for r in weights)
for r in plans:
 if r['all_gates']:assert r['P5_rank']==56 and r['preconditioned_rank']==57 and r['preconditioned_condition']<=1e8 and r['preconditioned_reproduction']<=1e-10 and r['value_l1']<=16 and r['gradient_l1']<=32 and r['hessian_l1']<=64 and r['coefficient_l1']<=10000
rank=[r for r in plans if r['P5_status']=='P5_rank_deficient'];physical=[r for r in plans if r['P5_status']=='ready' and not r['all_gates']];assert len(rank)==4 and len(physical)==4
analysis={'scope':'Four-query,24-stencil basis-preconditioning audit only. All57functions/span/unknowns/physical equations unchanged; original condition estimates retained separately. No full transition/evolution/generic-profile qualification.','precision':precision,'summary':summary,'same_span_reason':'The known B column is replaced by [B-P5_fit(B)]/weighted_residual_norm, and its exact query value/gradient/Hessian subtract the same polynomial. P5 and free residual amplitude are all retained; physical q values are never projected.','old_gate_pass_count':sum(r['original_all_gates'] for r in plans),'new_gate_pass_count':sum(r['all_gates'] for r in plans),'P5_rank_rejections':rank,'physical_amplification_rejections':physical,'plans':plans,'weight_comparisons':weights,'point126_fields':[r for r in fields if r['point']==126],'maximum_source_operator_change':max(r['original_source_change_max'] for r in fields),'guards_unchanged':{'physical_l1':[16,32,64],'condition':1e8,'reproduction':1e-10,'coefficient_l1':10000},'remaining_gates':['Complete every transition stencil with explicit unsupported geometry handling.','Check sensitivity to independent background value/jet uncertainty, not just unknown-field noise.','Retain matched constant/P5/strong nonspherical/profile controls and all-cell coupled science gates.'],'scientific_acceptance':False,'production_adopted':False}
with tempfile.TemporaryDirectory(prefix='orth-background-plot-',dir=out) as cache:
 os.environ['MPLCONFIGDIR']=cache;os.environ['XDG_CACHE_HOME']=cache
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 selected=[r for r in plans if r['donors']==256];x=list(range(len(selected)));fig,axes=plt.subplots(2,2,figsize=(12,9),layout='constrained')
 for offset,key,label in [(-.25,'original_condition','original57'),(0,'P5_condition','P5geometry'),(.25,'preconditioned_condition','residual57')]:axes[0,0].bar([v+offset for v in x],[r[key] for r in selected],width=.25,label=label)
 labels=[str(r['point'])+' '+r['field'] for r in selected];axes[0,0].set_xticks(x,labels,rotation=40,ha='right');axes[0,0].set_yscale('log');axes[0,0].set_title('Separate QR condition estimates;256 donors');axes[0,0].legend(fontsize=8)
 axes[0,1].semilogy(x,[r['original_reproduction'] for r in selected],'.-',label='original diagnostic');axes[0,1].semilogy(x,[r['preconditioned_reproduction'] for r in selected],'.-',label='preconditioned');axes[0,1].axhline(1e-10,color='k',ls=':',label='unchanged gate');axes[0,1].set_xticks(x,labels,rotation=40,ha='right');axes[0,1].set_title('Basis reproduction diagnostics');axes[0,1].legend(fontsize=8)
 axes[1,0].bar([0,1],[analysis['old_gate_pass_count'],analysis['new_gate_pass_count']]);axes[1,0].set_xticks([0,1],['original basis','orthogonal residual']);axes[1,0].set_ylim(0,24);axes[1,0].set_ylabel('ready /24');axes[1,0].set_title('Four rank and four physical-cap failures retained')
 for field in ['chi','alpha']:
  values=[];cases=['constant','Cartesian_P2','initial_B','scaled_B_07','strong_nonspherical','changed_radial']
  for case in cases:values.append(next(r['full_source_error_max'] for r in fields if r['point']==126 and r['field']==field and r['donors']==256 and r['case']==case))
  axes[1,1].plot(range(len(cases)),values,'.-',label=field)
 axes[1,1].set_yscale('symlog',linthresh=1e-12);axes[1,1].set_xticks(range(len(cases)),cases,rotation=35,ha='right');axes[1,1].set_title('Full physical-source error: finite profile errors remain');axes[1,1].legend()
 fig.suptitle('Same-span background basis preconditioning; no physical guard relaxation\nApple ARM long double has53mantissa bits, equal to double');fig.savefig(out/'orthogonal-background-audit.png',dpi=150);plt.close(fig)
analysis['source_sha256']=hashlib.sha256(path.read_bytes()).hexdigest();analysis['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();(out/'analysis.json').write_text(json.dumps(analysis,indent=2,allow_nan=False)+'\n');print(json.dumps({'old_ready':analysis['old_gate_pass_count'],'new_ready':analysis['new_gate_pass_count'],'precision':precision,'max_physical_weight_change':summary['physical_weight_change_max'],'max_full_source_change':analysis['maximum_source_operator_change']}))
